const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define three cities (point locations)
  const beijing = ee.Geometry.Point([116.4074, 39.9042]);
  const chongqing = ee.Geometry.Point([106.5516, 29.5630]);
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);
  const cities = { beijing, chongqing, wuhan };

  // Define periods
  const jan_start = '2020-01-01';
  const jan_end = '2020-01-20';
  const feb_start = '2020-02-10';
  const feb_end = '2020-02-25';

  // Load Sentinel-5P TROPOMI NO2 collection
  const collection = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  // Function to get mean NO2 for a period and location
  async function getMeanNO2(geom, startDate, endDate, label) {
    const col = collection
      .filterDate(startDate, endDate)
      .filterBounds(geom);

    const size = await col.size().getInfo();
    if (size === 0) {
      console.log(`${label}: 0 images found`);
      return null;
    }

    // Get mean value
    const meanImg = col.mean();
    const result = await meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 10000,
      maxPixels: 1e9
    }).getInfo();

    const meanVal = result.tropospheric_NO2_column_number_density;
    console.log(`${label}: ${size} images, Mean NO2: ${meanVal !== null ? meanVal.toFixed(6) : 'null'}`);
    return meanVal;
  }

  // Analysis
  const results = {};
  let allDataValid = true;

  for (const [cityName, geom] of Object.entries(cities)) {
    console.log(`\n--- ${cityName.toUpperCase()} ---`);

    const jan_mean = await getMeanNO2(geom, jan_start, jan_end, `${cityName} Jan 1-20`);
    const feb_mean = await getMeanNO2(geom, feb_start, feb_end, `${cityName} Feb 10-25`);

    if (jan_mean === null || feb_mean === null) {
      console.log(`${cityName}: Missing data for one or both periods`);
      allDataValid = false;
      results[cityName] = null;
      continue;
    }

    // Validate range (NO2 typically 0-5 μmol/m²)
    if (jan_mean < 0 || jan_mean > 10 || feb_mean < 0 || feb_mean > 10) {
      console.log(`${cityName}: Value out of valid range`);
      results[cityName] = null;
      allDataValid = false;
      continue;
    }

    const decreased = feb_mean < jan_mean;
    results[cityName] = { jan: jan_mean, feb: feb_mean, decreased };
    console.log(`${cityName}: Jan=${jan_mean.toFixed(6)}, Feb=${feb_mean.toFixed(6)}, Decreased=${decreased}`);
  }

  // Determine final answer
  console.log('\n--- FINAL RESULT ---');

  if (!allDataValid) {
    console.log('C1');
    return;
  }

  const validCities = Object.values(results).filter(r => r !== null);
  if (validCities.length === 0) {
    console.log('C1');
    return;
  }

  if (validCities.length < 3) {
    console.log('C1');
    return;
  }

  // Check if ALL three cities decreased
  const allDecreased = validCities.every(r => r.decreased);
  console.log(`All three cities decreased: ${allDecreased}`);

  if (allDecreased) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
